import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Track opponent behavior and recent outcomes
    cc = cd = dc = dd = 0
    for mine, opp in history:
        if mine == 'C' and opp == 'C':
            cc += 1
        elif mine == 'C' and opp == 'D':
            cd += 1
        elif mine == 'D' and opp == 'C':
            dc += 1
        else:
            dd += 1

    # Last actions
    last_mine, last_opp = history[-1]

    # If opponent has defected at all, become less forgiving but still probe
    opp_defections = cd + dd
    opp_cooperations = cc + dc

    # Early-game: establish cooperation, but punish immediately
    if n < 10:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # If opponent seems mostly cooperative, cooperate but occasionally test
    if opp_defections == 0:
        # Perfectly cooperative so far: cooperate, but rare random test
        if n > 20 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # Compute recent trend over last 10 rounds
    recent = history[-10:]
    rec_def = 0
    rec_coop = 0
    for mine, opp in recent:
        if opp == 'D':
            rec_def += 1
        else:
            rec_coop += 1

    # If recent opponent defection rate is high, defect more
    if rec_def >= 7:
        return 'D'
    if rec_def >= 4:
        # Mix: defect often, but cooperate sometimes to avoid full collapse
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    # If we defected last and opponent cooperated, exploit again
    if last_mine == 'D' and last_opp == 'C':
        return 'D'

    # If opponent defected last, retaliate, but possibly forgive after punishing
    if last_opp == 'D':
        # Count consecutive defections by opponent
        streak = 0
        for mine, opp in reversed(history):
            if opp == 'D':
                streak += 1
            else:
                break
        if streak >= 2:
            return 'D'
        # Single defection: punish once, then maybe return to C
        if last_mine == 'D':
            return 'C'
        return 'D'

    # Opponent cooperated last. If we defected, consider returning to cooperation
    if last_mine == 'D':
        # If we've been defecting a lot relative to cooperation, soften
        if dc > cc + 2:
            return 'C'
        # Otherwise continue exploiting occasionally
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    # Default: cooperate
    return 'C'

